def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = [0, 0]  # top-single T, bottom-single T

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(cells) != 4:
                continue
            rows = {}
            for y, x in cells:
                rows.setdefault(y, []).append(x)
            if len(rows) != 2:
                continue
            ys = sorted(rows)
            if ys[1] != ys[0] + 1:
                continue
            if len(rows[ys[0]]) == 1 and len(rows[ys[1]]) == 3:
                counts[0] += 1
            elif len(rows[ys[0]]) == 3 and len(rows[ys[1]]) == 1:
                counts[1] += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for i in range(min(counts[0], 4)):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(min(counts[1], 4)):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out
